mapper.select:
select t.id, t.trade_type, t.target_name, t.plan_type, t.plan_content, t.plan_start_time, t.plan_end_time, t.create_time, t.current_price, t.plan_price, t.open_price, t.actual_price, t.close_price, t.trade_status, t.comply_rule_ids, t.violate_rule_ids, t.trade_result, t.trade_fail_type, t.result_review, t.owner, t.is_use_plan from t_trial_transaction_record t
and t.trade_type in
#{item}
and t.target_name like concat('%', #{targetName}, '%')
and t.plan_type in
#{item}
and t.plan_start_time >= #{planStartTime}
and t.plan_start_time <= #{planEndTime}
and t.trade_status in
#{item}
and t.trade_result in
#{item}
and t.trade_fail_type in
#{item}
and t.is_use_plan = #{isUsePlan}
and t.owner = #{owner}
order by t.create_time desc
